window.__LIBQ=window.__LIBQ||{};window.__LIBQ["the-gioi-hoan-my"]=window.__LIBQ["the-gioi-hoan-my"]||{};window.__LIBQ["the-gioi-hoan-my"]["q14"]=window.__LIBQ["the-gioi-hoan-my"]["q14"]||{};window.__LIBQ["the-gioi-hoan-my"]["q14"]["factions"]={"updatedAt":"2026-07-26","count":43,"factions":[{"id":"thien-than-the-luc","name":"Thiên Thần Thư Viện","cn":"","aliases":[],"type":"hoc-vien","typeLabel":"Học viện","diaBan":"Thiên Thần Thư Viện","nhanVatChinh":["Mạnh Thiên Chính","Thạch Hạo"],"blurb":"Thiên Thần, được nhắc đến trong tiến trình với danh xưng Thiên Thần Thư Viện, là một đạo thống có đệ tử từng tham gia Tiên cổ. Về sau, thư viện hợp nhất với Tiên Viện và Thánh Viện nhằm chuẩn bị nhân lực cho chiến trường Biên.","detail":"Thiên Thần từng được Thạch Hạo liệt kê cùng Thiên quốc, Minh thổ, Ma Quỳ viên và Thú hải trong số các thế lực có đệ tử cần dò tìm tại Tiên cổ. Ở giai đoạn chiến sự biên cương, Thiên Thần Thư Viện tham gia bàn bạc việc hợp nhất với Tiên Viện và Thánh Viện, đồng thời tiếp nhận tin báo nguy từ biên cư @c1303. Đại trưởng lão Mạnh Thiên Chính của thư viện được giao ở lại trấn thủ Đại Xích Thiên @c1332. Sau đó, ba thư viện chính thức sáp nhập để chuẩn bị nhân lực cho chiến trường Biên @c1354.","quanHe":"Đang chuẩn bị hợp nhất với Tiên Viện và Thánh Viện.","trangThai":"Đã hợp nhất cùng tam viện","capNhatToi":"@c1303","tabs":{"tienTrinh":[{"chuong":"@c1303","loai":"liên minh","importance":"normal","giaiDoan":"Chuẩn bị hợp nhất ba viện","text":"Thiên Thần Thư Viện bàn việc hợp nhất với Tiên Viện và Thánh Viện, đồng thời tiếp nhận tin báo nguy từ biên cương.","anchor":"Tiên Viện, Thánh Viện, Thiên Thần Thư Viện sắp sửa hợp lại cùng nhau"},{"chuong":"@c1332","loai":"nhắc tới","importance":"normal","giaiDoan":"Trấn thủ Đại Xích Thiên","text":"Đại trưởng lão Mạnh Thiên Chính của Thiên Thần Thư Viện được giao ở lại trấn thủ Đại Xích Thiên.","anchor":"yêu cầu Thiên Thần Thư Viện Đại trưởng lão Mạnh Thiên Chính trấn thủ tại chỗ này"},{"chuong":"@c1354","loai":"sáp nhập","importance":"major","giaiDoan":"Tam viện hợp nhất","text":"Thiên Thần Thư Viện chính thức hợp nhất với Tiên Viện và Thánh Viện để chuẩn bị nhân lực cho chiến trường Biên Hoang.","anchor":"Tam viện hợp nhất, thật sự thành hàng rồi!","trangThaiMoc":"Hợp nhất"}]},"nguon":["@c1303","@c1332","@c1354"],"thanhVien":[{"ten":"Mạnh Thiên Chính","chucVu":"Đại trưởng lão","tuChuong":"@c1332","trangThai":"gan-bo"}],"dacDiem":"Một thư viện, đạo thống có Đại trưởng lão Mạnh Thiên Chính, về sau hợp nhất với Tiên Viện và Thánh Viện trước tình thế chiến trường Biên.","congNang":["Tiếp nhận tin báo nguy từ biên cư và tham gia ứng phó tình hình chiến trường Biên @c1303","Cử Đại trưởng lão Mạnh Thiên Chính trấn thủ Đại Xích Thiên @c1332","Hợp nhất với Tiên Viện và Thánh Viện để chuẩn bị nhân lực cho chiến trường Biên @c1354"]},{"id":"tien-vien-the-luc","name":"Tiên Viện","cn":"","aliases":[],"type":"hoc-vien","typeLabel":"Học viện","diaBan":"","nhanVatChinh":[],"blurb":"Tiên Viện là một trong ba học viện tham gia hợp nhất với Thánh Viện và Thiên Thần Thư Viện nhằm cùng bồi dưỡng thiên tài trước nguy cơ từ dị vực. Trước khi chính thức sáp nhập, trưởng lão của viện đã cảnh báo các đệ tử tăng cường tu luyện để sẵn sàng ứng phó chiến sự.","detail":"Tiên Viện tham gia thương nghị kế hoạch hợp nhất ba viện và lựa chọn căn cơ chung. Trong bối cảnh dị vực có thể tấn công bất cứ lúc nào, trưởng lão Tiên Viện yêu cầu các đệ tử tập trung tu luyện, chuẩn bị đối phó nguy cơ. Sau đó, Tiên Viện chính thức hợp nhất với Thánh Viện và Thiên Thần Thư Viện để cùng bồi dưỡng thiên tài trước khi tiến quân. @c1303 @c1354","quanHe":"Đang chuẩn bị hợp nhất với Thánh Viện và Thiên Thần Thư Viện.","trangThai":"Đã hợp nhất cùng tam viện","capNhatToi":"@c1303","tabs":{"tienTrinh":[{"chuong":"@c1303","loai":"liên minh","importance":"normal","giaiDoan":"Chuẩn bị hợp nhất ba viện","text":"Tiên Viện tham gia kế hoạch hợp nhất và cảnh báo đệ tử phải chuẩn bị trước nguy cơ dị vực tấn công.","anchor":"Đều lúc nào, các ngươi còn ở cãi vã những này, vẫn là nỗ lực tăng lên tự thân tu vi đi"},{"chuong":"@c1354","loai":"sáp nhập","importance":"major","giaiDoan":"Tam viện hợp nhất","text":"Tiên Viện chính thức hợp nhất với Thánh Viện và Thiên Thần Thư Viện để cùng bồi dưỡng thiên tài trước khi tiến ra Biên Hoang.","anchor":"Tam viện hợp nhất, thật sự thành hàng rồi!","trangThaiMoc":"Hợp nhất"}]},"nguon":["@c1303","@c1354"],"dacDiem":"Một trong ba học viện hợp nhất để bồi dưỡng thiên tài và chuẩn bị trước nguy cơ dị vực.","congNang":["Tham gia hợp nhất ba viện để cùng bồi dưỡng thiên tài trước khi tiến quân. @c1354","Cảnh báo và thúc giục đệ tử tăng cường tu luyện nhằm chuẩn bị đối phó dị vực. @c1303"]},{"id":"tu-gia","name":"Từ gia","cn":"","aliases":["Trường Sinh hoàng triều Từ gia"],"type":"gia-toc","typeLabel":"Gia tộc","diaBan":"","nhanVatChinh":["Từ Minh Hiên","Yêu Nguyệt"],"blurb":"Từ gia là thế lực đã cho Mạnh Thiên Chính mượn Tiên cổ chiến kỳ. Hành động này xác lập quan hệ liên minh cùng tiến cùng lui giữa hai bên.","detail":"Tại thời điểm Mạnh Thiên Chính tiến vào tổ địa Vương gia, Từ gia đã cho ông mượn Tiên cổ chiến kỳ, qua đó công khai thể hiện lập trường hợp tác và xác lập thế cùng tiến cùng lui với Mạnh Thiên Chính để đối phó Vương gia. Từ gia cũng là gia tộc của Từ Minh Hiên và Yêu Nguyệt, đồng thời được xác định là túc địch của Vương gia.","lanhDaoHienThoi":"Từ Minh Hiên","quanHe":"Kết minh với Mạnh Thiên Chính và đối địch Vương gia.","trangThai":"Đã kết minh với Mạnh Thiên Chính","thanhVien":[{"ten":"Từ Minh Hiên","chucVu":"Nhân vật chủ chốt","tuChuong":"@c1303","trangThai":"Đang hoạt động"},{"ten":"Yêu Nguyệt","chucVu":"Công chúa","tuChuong":"@c1303","trangThai":"Đang hoạt động"}],"capNhatToi":"@c1303","tabs":{"tienTrinh":[{"chuong":"@c1303","loai":"liên minh","importance":"major","giaiDoan":"Kết minh chống Vương gia","text":"Từ gia cho Mạnh Thiên Chính mượn Tiên cổ chiến kỳ, qua đó xác lập thế cùng tiến cùng lui giữa hai bên.","anchor":"Từ gia đem Tiên cổ chiến kỳ ượn Đại trưởng lão, hiển nhiên là một loại kết minh, xem như là cùng tiến cùng lui"}]},"nguon":["@c1303"],"dacDiem":"Có Tiên cổ chiến kỳ và liên minh cùng tiến cùng lui với Mạnh Thiên Chính; là túc địch của Vương gia."},{"id":"bach-cot-son","name":"Bạch Cốt Sơn","cn":"","type":"cuong-toc","typeLabel":"Siêu cấp cường tộc","diaBan":"Mật địa Bạch Cốt Sơn","nhanVatChinh":[],"blurb":"Một siêu cấp cường tộc cư trú tại mật địa phủ đầy bạch cốt, nơi người ngoài rất khó tiến vào. Khi tiếng kèn Chân Long vang lên, tộc chủ dẫn toàn tộc cao thủ tới hội quân.","detail":"Địa bàn của Bạch Cốt Sơn có bạch cốt trải khắp nơi và được truyền rằng các sinh linh trong đó đều do cốt thần biến thành. Tộc chủ cùng cao thủ toàn tộc xuất hiện trên một chiếc bạch cốt chiến thuyền khổng lồ để tham gia lực lượng tiếp viện Đại Xích Thiên.","quyMo":"Siêu cấp cường tộc","trangThai":"Đã xuất động chi viện Đại Xích Thiên","capNhatToi":"@c1305","nguon":["@c1305"]},{"id":"muc-lan-toc","name":"Mục Lan tộc","cn":"","type":"dai-toc","typeLabel":"Đại tộc","diaBan":"","nhanVatChinh":[],"blurb":"Một đại tộc trên chín tầng trời sở hữu chiến thuyền được luyện chế từ một ngôi sao thần. Toàn tộc cao thủ đáp lại tiếng kèn Chân Long và tới tham gia đội quân tiếp viện.","detail":"Cao thủ Mục Lan tộc đồng loạt xuất động trên một chiến thuyền mang phong cách cổ xưa, được luyện thành từ cả một ngôi sao thần. Họ hội quân cùng các đại cường tộc trước khi đoàn chiến thuyền tiến về Đại Xích Thiên.","trangThai":"Đã xuất động chi viện Đại Xích Thiên","capNhatToi":"@c1305","tabs":{"tienTrinh":[{"chuong":"@c1305","loai":"liên minh","importance":"normal","giaiDoan":"Hội quân chống dị vực","text":"Mục Lan tộc điều động toàn bộ cao thủ tới hội quân và chuẩn bị tiến về Đại Xích Thiên.","anchor":"Mục lan tộc cả tộc cao thủ đều tới"}]},"nguon":["@c1305"]},{"id":"xa-da-xoa-toc","name":"Xà Dạ Xoa tộc","cn":"","type":"chung-toc","typeLabel":"Vương tộc dị vực","diaBan":"Dị vực","nhanVatChinh":["Xà Dạ Xoa"],"blurb":"Một trong các Vương tộc hùng mạnh của dị vực.","detail":"Tộc này có tuổi trẻ cường giả Xà Dạ Xoa tham gia cuộc đối đầu với Cửu Thiên Thập Địa tại phế tích gần vực sâu màu đen.","quyMo":"Vương tộc","thanhVien":[{"ten":"Xà Dạ Xoa","chucVu":"Tuổi trẻ cường giả","tuChuong":"@c1312","trangThai":"đang hoạt động"}],"capNhatToi":"@c1312","tabs":{"tienTrinh":[{"chuong":"@c1312","loai":"nhắc tới","importance":"normal","giaiDoan":"Xuất chiến","text":"Xà Dạ Xoa tộc được xác nhận là một Vương tộc dị vực khi cường giả trẻ tuổi của tộc tham chiến.","anchor":"Xà Dạ Xoa! chủng tộc này quá mạnh mẽ, được xưng dị vực Vương tộc một trong"}]},"nguon":["@c1312"]},{"id":"hoang-kim-ma-dieu-nhat-toc","name":"Hoàng Kim Ma Điểu nhất tộc","cn":"","aliases":[],"type":"chung-toc","typeLabel":"Chủng tộc Dị vực","diaBan":"Dị Giới","nhanVatChinh":["Hoàng Kim Ma Điểu"],"blurb":"Hoàng Kim Ma Điểu nhất tộc là một chủng tộc Dị vực từng gây tổn thất lớn cho Cửu Thiên Thập Địa. Về sau, tổ địa của tộc này bị Vô Chung mang tiên chung đánh phá, khiến cả tộc gần như bị tiêu diệt, song vẫn còn thành viên sống sót và tham gia cuộc quyết đấu giữa hai giới.","detail":"Hoàng Kim Ma Điểu nhất tộc có nguồn gốc từ Dị vực và từng là một thế lực gây tổn thất lớn cho Cửu Thiên Thập Địa. Trong quá khứ, Vô Chung một mình mang tiên chung xông vào Dị Giới, phá hủy tổ địa và gần như tiêu diệt toàn tộc @c1315. Đến thời điểm hiện tại, tộc này vẫn còn thành viên sống sót, xuất hiện trong cuộc quyết đấu giữa hai giới.","nguonGoc":"Dị vực","trangThai":"Suy yếu, vẫn còn thành viên sống sót","thanhVien":[{"ten":"Hoàng Kim Ma Điểu","chucVu":"Vương giả trẻ tuổi","tuChuong":"@c1315","trangThai":"Còn sống"}],"tabs":{"tienTrinh":[{"chuong":"@c1315","loai":"nhắc tới","importance":"major","giaiDoan":"Tổ địa từng bị phá hủy","text":"Quá khứ Hoàng Kim Ma Điểu nhất tộc từng bị Vô Chung mang tiên chung đánh vào Dị Giới, phá hủy tổ địa và gần như tiêu diệt toàn tộc.","anchor":"Hoàng Kim Ma Điểu nhất tộc đã từng bị diệt","trangThaiMoc":"Suy yếu, còn thành viên sống sót"}]},"capNhatToi":"@c1315","nguon":["@c1315"],"uyLuc":"Từng gây tổn thất lớn cho Cửu Thiên Thập Địa.","dacDiem":"Chủng tộc Dị vực có tổ địa từng bị Vô Chung phá hủy, khiến toàn tộc gần như diệt vong."},{"id":"bach-ngan-vuong-toc","name":"Bạch Ngân Vương tộc","cn":"","type":"vuong-toc","typeLabel":"Vương tộc Dị vực","diaBan":"Kỳ Long Cổ Sơn Mạch","nhanVatChinh":["Ngân Linh"],"blurb":"Vương tộc cổ xưa của Dị vực cư trú tại Kỳ Long Cổ Sơn Mạch.","detail":"Tộc này sở hữu thần thông kỳ dị có thể biến đối thủ thành chất lỏng kim loại. Ngân Linh giết một thiên tài Thánh Viện mà chưa cần sử dụng át chủ bài của tộc.","dacDiem":"Có thần thông biến đối thủ thành chất lỏng kim loại.","thanhVien":[{"ten":"Ngân Linh","chucVu":"Tuổi trẻ Vương giả","tuChuong":"@c1316","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1316","loai":"nhắc tới","importance":"normal","giaiDoan":"Ngân Linh giành chiến thắng","text":"Thành viên Ngân Linh giết một thiên tài Thánh Viện mà chưa cần thi triển thần thông át chủ bài của Bạch Ngân Vương tộc.","anchor":"cai tộc có thể đem đối thủ hóa thành vi kim loại chất lỏng, có kỳ dị thần thông"}]},"capNhatToi":"@c1316","nguon":["@c1316"]},{"id":"duong-ngo-toc","name":"Đường Ngô tộc","cn":"","type":"vuong-toc","typeLabel":"Vương tộc Dị vực","diaBan":"Dị vực","nhanVatChinh":["Đường Ngô"],"blurb":"Vương tộc lãnh huyết của Dị vực nổi danh với sát phạt dữ dội.","detail":"Thành viên Đường Ngô có thân thể cực kỳ cứng chắc và giết Tử Nhật Thiên Quân trong cuộc quyết đấu tại biên cương.","dacDiem":"Tộc lãnh huyết có sát phạt chi khí mạnh mẽ.","thanhVien":[{"ten":"Đường Ngô","chucVu":"Tuổi trẻ Vương giả","tuChuong":"@c1316","trangThai":"đang hoạt động"}],"tabs":{"tienTrinh":[{"chuong":"@c1316","loai":"nhắc tới","importance":"normal","giaiDoan":"Đường Ngô giành chiến thắng","text":"Đường Ngô của tộc này giết Tử Nhật Thiên Quân và cướp Hồng Mông Tử Khí chủng.","anchor":"Đây là dị vực lãnh huyết Vương tộc, cai tộc từ trước đến nay sát phạt chi khí ngập trời"}]},"capNhatToi":"@c1316","nguon":["@c1316"]},{"id":"an-lan-toc","name":"An Lan tộc","cn":"","aliases":["An Lan bộ tộc","An Lan gia tộc"],"type":"gia-toc","typeLabel":"Gia tộc","diaBan":"Cổ địa An Lan","nhanVatChinh":["Triển Phong"],"blurb":"Dòng họ đáng sợ của Dị vực, có nhân khẩu ít nhưng khiến nhiều cường tộc kính sợ. Cổ địa của tộc đã rất lâu không có người trẻ tuổi bước ra.","detail":"Triển Phong mang một phần tư chân huyết An Lan do ngoại tổ mẫu xuất thân từ gia tộc này. Việc hô gọi dòng họ còn làm hiển hiện binh khí và một phần sức mạnh của tồn tại vô thượng gắn với An Lan.","nguonGoc":"Dòng họ thuộc Dị vực","quyMo":"Nhân khẩu ít nhưng có uy thế khiến nhiều cường tộc Dị vực kính sợ.","caoThuManhNhat":"Tồn tại vô thượng họ An Lan","thanhVien":[{"ten":"Triển Phong","chucVu":"Hậu duệ ngoại hệ mang một phần tư chân huyết","tuChuong":"@c1320","trangThai":"Đang hoạt động"}],"trangThai":"Đang tồn tại","capNhatToi":"@c1320","tabs":{"tienTrinh":[{"chuong":"@c1320","loai":"nhắc tới","importance":"normal","giaiDoan":"Huyết thống được tiết lộ","text":"Lai lịch của An Lan tộc được công khai khi Triển Phong xác nhận mình mang một phần tư chân huyết của dòng họ.","anchor":"An Lan, cái họ này sinh linh ít ỏi, tộc này phi thường đáng sợ, nhưng nhân khẩu thật sự có hạn","trangThaiMoc":"Đang tồn tại"}]},"nguon":["@c1320"]},{"id":"hoa-nham-vuong-toc","name":"Hỏa nham Vương tộc","cn":"","type":"vuong-toc","typeLabel":"Vương tộc Dị Vực","diaBan":"Biển dung nham thuộc Dị Vực","nhanVatChinh":["Hỏa Nham Vương"],"blurb":"Vương tộc Dị Vực được thai nghén trong biển dung nham, có năng lực khống hỏa bẩm sinh.","detail":"Thành viên của tộc có thể vận dụng Thái Dương chi tinh và ngưng tụ lực lượng hỏa mạch. Tại chiến trường hai giới, Hỏa Nham Vương của tộc bị Thạch Hạo đánh chết sau khi Tiên Quy giáp phiến chọn làm đối thủ.","nguonGoc":"Được thai nghén trong biển dung nham.","quyMo":"Vương tộc Dị Vực","caoThuManhNhat":"Hỏa Nham Vương trong phạm vi thông tin tại @c1323","thanhVien":[{"ten":"Hỏa Nham Vương","chucVu":"Vương giả trẻ tuổi","tuChuong":"@c1323","trangThai":"Tử trận"}],"trangThai":"Tồn tại","capNhatToi":"@c1323","tabs":{"tienTrinh":[{"chuong":"@c1323","loai":"khai chiến","importance":"normal","giaiDoan":"Vương giả trẻ tuổi tử trận","text":"Hỏa Nham Vương đại diện cho tộc giao chiến với Thạch Hạo và bị đánh chết.","anchor":"chủng tộc này là ở dung nham trong biển bị dựng dục ra đến","trangThaiMoc":"Mất một Vương giả trẻ tuổi"}]},"nguon":["@c1323"]},{"id":"song-tu-vuong-toc","name":"Song Tử Vương tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc dị vực","diaBan":"Dị vực","nhanVatChinh":["Song Tử Vương"],"blurb":"Chủng tộc dị vực có đặc điểm hai đầu, giỏi phá vạn pháp và thích hợp tu luyện các loại bí thuật.","detail":"Thành viên Song Tử Vương dùng hai đầu đồng thời ngâm bí ngôn, vận dụng sức mạnh quang ám và thần chú quấy nhiễu hoàn mỹ cổ chủng.","dacDiem":"Hai đầu có thể phối hợp thi triển bí thuật và phá vạn pháp.","thanhVien":[{"ten":"Song Tử Vương","chucVu":"Vương giả trẻ tuổi","tuChuong":"@c1324","trangThai":"tu-vong"}],"trangThai":"Không rõ","capNhatToi":"@c1324","nguon":["@c1324"]},{"id":"toi-huyet-hau-nhan","name":"Tội Huyết hậu nhân","cn":"","type":"nhom-huyet-mach","typeLabel":"Nhóm huyết mạch","diaBan":"Cửu Thiên Thập Địa","nhanVatChinh":["Thạch Hạo","Thạch Nghị","Tần Hạo"],"blurb":"Một cách gọi dành cho một nhóm hậu duệ tại Cửu Thiên Thập Địa. Hoàng Kim Ma Điểu tuyên bố họ là con cháu của những kỳ tài từng quy thuận Dị Vực, nhưng lời giải thích này chưa được xác nhận.","detail":"Lời tuyên bố của Hoàng Kim Ma Điểu khiến Thạch Hạo, Thạch Nghị và Tần Hạo chấn động. Thạch Hạo không chấp nhận tổ tiên Thạch tộc là tội nhân và bắt đầu nghi vấn thân phận thật sự của Tội Huyết nhất mạch.","nguonGoc":"Theo lời Hoàng Kim Ma Điểu, đây là hậu duệ của những kỳ tài từng đầu nhập Dị Vực.","trangThai":"Nguồn gốc chưa được xác nhận","capNhatToi":"@c1325","tabs":{"tienTrinh":[{"chuong":"@c1325","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ nguồn gốc khả nghi","text":"Hoàng Kim Ma Điểu tuyên bố Tội Huyết hậu nhân là con cháu của những kỳ tài từng quy thuận Dị Vực, nhưng Thạch Hạo không chấp nhận cách giải thích này.","anchor":"bọn họ để lại ở ngươi giới đời sau được gọi là Tội Huyết hậu nhân."}]},"nguon":["@c1325"]},{"id":"kim-giap-toc","name":"Kim Giáp tộc","cn":"","type":"vuong-toc","typeLabel":"Vương tộc dị vực","diaBan":"Dị vực","nhanVatChinh":["Cao thủ trẻ tuổi Kim Giáp Vương tộc"],"blurb":"Kim Giáp tộc là một Vương tộc dị vực hình thành từ huyết thống pha trộn giữa Nghiệt Long, Huyền Quy và một Vương tộc khác.","detail":"Bộ tộc nổi danh nhờ mai rùa hoàng kim có sức phòng ngự kinh người. Một vương giả trẻ tuổi của tộc được Tiên Quy Giáp lựa chọn và bị Thạch Hạo giết trên chiến trường.","nguonGoc":"Hỗn huyết giữa Nghiệt Long, Huyền Quy và một Vương tộc dị vực.","capBac":"Vương tộc","tranPhai":"Mai rùa hoàng kim và tổ thuật Kim Giáp tộc","trangThai":"Tồn tại","thanhVien":[{"ten":"Cao thủ trẻ tuổi Kim Giáp Vương tộc","chucVu":"Vương giả trẻ tuổi","tuChuong":"@c1327","trangThai":"tu-vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1327","loai":"nhắc tới","importance":"normal","giaiDoan":"Một vương giả chết trận","text":"Kim Giáp tộc được xác nhận là bộ tộc hỗn huyết có sức phòng ngự mạnh, nhưng vương giả trẻ tuổi đại diện cho tộc bị Thạch Hạo giết.","anchor":"Cái gọi là Kim Giáp tộc, là hỗn huyết tộc duệ, đến cuối cùng rốt cục hình thành chính mình bộ tộc.","trangThaiMoc":"Tồn tại"}]},"capNhatToi":"@c1327","nguon":["@c1327"]},{"id":"vuong-toc-cua-nam-tu-co-vay-o-mi-tam","name":"Vương tộc của nam tử có vảy ở mi tâm","cn":"","type":"vuong-toc","typeLabel":"Vương tộc dị vực","diaBan":"Dị vực","nhanVatChinh":["Nam tử trẻ tuổi có vảy ở mi tâm"],"blurb":"Một Vương tộc đỉnh cấp chưa được nêu tên tại dị vực, có tổ tiên vốn là kỳ tài của Cửu Thiên Thập Địa.","detail":"Theo lời nam tử có vảy ở mi tâm, tổ tiên của bộ tộc đã chủ động xin đến góp sức cho dị vực. Đến hiện tại, bộ tộc đã trở thành Vương tộc đỉnh cấp có quyền thế lớn.","nguonGoc":"Bắt nguồn từ kỳ tài Cửu Thiên Thập Địa xin đến góp sức cho dị vực.","capBac":"Vương tộc đỉnh cấp","quanHe":"Thuộc phe dị vực.","trangThai":"Hưng thịnh","thanhVien":[{"ten":"Nam tử trẻ tuổi có vảy ở mi tâm","chucVu":"Vương giả trẻ tuổi","tuChuong":"@c1327","trangThai":"tu-vong"}],"tabs":{"tienTrinh":[{"chuong":"@c1327","loai":"nhắc tới","importance":"normal","giaiDoan":"Nguồn gốc được xác nhận","text":"Nam tử có vảy ở mi tâm xác nhận tổ tiên đã xin đến góp sức cho dị vực và bộ tộc hiện là Vương tộc đỉnh cấp.","anchor":"bây giờ bộ tộc ta đã thành vì là đỉnh cấp Vương tộc, quyền khuynh đương đại","trangThaiMoc":"Hưng thịnh"}]},"capNhatToi":"@c1327","nguon":["@c1327"]},{"id":"hac-gia","name":"Hạc gia","cn":"","aliases":["Hạc tộc"],"type":"gia-toc","typeLabel":"Gia tộc","diaBan":"Dị vực","nhanVatChinh":["Hạc Vô Song","Nam tử tóc vàng Hạc gia"],"blurb":"Gia tộc của Hạc Vô Song tại Dị vực, có hậu duệ tóc vàng xuất hiện ở chiến trường biên cương Đại Xích Thiên.","detail":"Sự xuất hiện của hậu duệ Hạc gia khiến các vương giả trẻ tuổi Dị vực tin rằng phe mình đã có đủ lực lượng để giết Thạch Hạo dù người An Lan tộc không đến.","nguonGoc":"Gia tộc của Hạc Vô Song","thanhVien":[{"ten":"Hạc Vô Song","chucVu":"Gia tổ","tuChuong":"@c1328","trangThai":"thành viên"},{"ten":"Nam tử tóc vàng Hạc gia","chucVu":"Hậu duệ","tuChuong":"@c1328","trangThai":"thành viên"}],"trangThai":"Hoạt động","capNhatToi":"@c1328","tabs":{"tienTrinh":[{"chuong":"@c1328","loai":"nhắc tới","importance":"normal","giaiDoan":"Hậu duệ đến chiến trường","text":"Một hậu duệ tóc vàng của Hạc gia xuất hiện tại chiến trường và được các vương giả trẻ tuổi Dị vực cung kính nghênh đón.","anchor":"An Lan tộc người không có đến, nhưng Hạc gia người đến, cũng đầy đủ rồi!"}]},"nguon":["@c1328"]},{"id":"doan-di-vuc-tai-co-gioi-phong-an","name":"Đoàn dị vực tại cổ giới phong ấn","cn":"","type":"đoàn viễn chinh","typeLabel":"Đoàn Dị vực","diaBan":"Cửa vào cổ giới phong ấn","nhanVatChinh":["Lão giả dị vực ra lệnh luyện huyết","Lão giả dị vực nhận ra huyết hóa hình","Vương giả trẻ tuổi dị vực","Lão giả dị vực bị xé đôi"],"blurb":"Đoàn người Dị vực mang Luyện Tiên Hồ tới tranh quyền tiến vào cổ giới và thu luyện Tiên huyết.","detail":"Đoàn bị huyết linh cùng các Tiên khí tàn khuyết liên tục công kích. Một vương giả trẻ tuổi và một lão giả rời khỏi phạm vi bảo hộ rồi tử trận.","quanHe":"Đối địch với đoàn Cửu Thiên của Mạnh Thiên Chính trong cuộc tranh vào cổ giới.","trangThai":"Bị chặn ngoài cửa cổ giới và chịu tổn thất nhân mạng","thanhVien":[{"ten":"Lão giả dị vực ra lệnh luyện huyết","chucVu":"Người ra lệnh","tuChuong":"@c1336","trangThai":"đang hoạt động"},{"ten":"Lão giả dị vực nhận ra huyết hóa hình","chucVu":"Thành viên","tuChuong":"@c1336","trangThai":"đang hoạt động"},{"ten":"Vương giả trẻ tuổi dị vực","chucVu":"Thành viên","tuChuong":"@c1336","trangThai":"đã tử trận"},{"ten":"Lão giả dị vực bị xé đôi","chucVu":"Cao thủ","tuChuong":"@c1336","trangThai":"đã tử trận"}],"tabs":{"tienTrinh":[{"chuong":"@c1336","loai":"khai chiến","importance":"normal","giaiDoan":"Tranh vào cổ giới","trangThaiMoc":"Tổn thất ít nhất hai thành viên","text":"Đoàn Dị vực dùng Luyện Tiên Hồ thu luyện Tiên huyết nhưng bị huyết linh đánh chặn, khiến ít nhất hai thành viên tử trận.","anchor":"Dị vực mọi người biến sắc, bọn họ chán ghét Tiên huyết mùi vị"}]},"capNhatToi":"@c1336","nguon":["@c1336"]},{"id":"doan-cuu-thien-cua-manh-thien-chinh","name":"Đoàn Cửu Thiên của Mạnh Thiên Chính","cn":"","type":"đoàn Cửu Thiên","typeLabel":"Đoàn Cửu Thiên","diaBan":"Cửa vào cổ giới phong ấn","nhanVatChinh":["Mạnh Thiên Chính","Thạch Hạo"],"blurb":"Đoàn Cửu Thiên do Mạnh Thiên Chính dẫn dắt rời cự bi để tranh vào cổ giới trước Dị vực.","detail":"Đoàn sử dụng Đại La Kiếm Thai và Thiết Huyết Chiến Kỳ để tiến lên. Khi huyết linh bạo động, họ tạm thời ở phía sau đoàn Dị vực nhưng vẫn chưa thể vượt qua cửa vào.","lanhDaoHienThoi":"Mạnh Thiên Chính","quanHe":"Đối địch với đoàn Dị vực tại cổ giới phong ấn.","trangThai":"Bị chặn ngoài cửa cổ giới","thanhVien":[{"ten":"Mạnh Thiên Chính","chucVu":"Lãnh đạo","tuChuong":"@c1336","trangThai":"đang hoạt động"},{"ten":"Thạch Hạo","chucVu":"Thành viên","tuChuong":"@c1336","trangThai":"đang hoạt động"}],"lanhDaoMoc":[{"ten":"Mạnh Thiên Chính","tuChuong":"@c1336","denChuong":""}],"tabs":{"tienTrinh":[{"chuong":"@c1336","loai":"khai chiến","importance":"normal","giaiDoan":"Tranh vào cổ giới","trangThaiMoc":"Bị huyết linh chặn tại cửa vào","text":"Đoàn Cửu Thiên theo Mạnh Thiên Chính rời cự bi và tranh đường vào cổ giới, nhưng phải dừng lại trước huyết linh cùng Tiên khí tàn khuyết.","anchor":"may mà là dị vực người đỉnh ở phía trước"}]},"capNhatToi":"@c1336","nguon":["@c1336"]},{"id":"bo-toc-phuong-hoang","name":"Bộ tộc Phượng Hoàng","cn":"","type":"chung-toc","typeLabel":"Chủng tộc","diaBan":"Tổ địa bộ tộc Phượng Hoàng","nhanVatChinh":["Vị thành niên đọa lạc Huyết Hoàng","Thi thể Phượng Hoàng trưởng thành"],"blurb":"Bộ tộc Phượng Hoàng có ngôn ngữ riêng và một tổ địa từng sinh trưởng thần thụ dùng để luyện Phượng ngô Tiên cầm.","detail":"Không ai trong hai phe hiện diện hiểu được ngôn ngữ mà Huyết Hoàng dùng để giao lưu với bộ xương. Tại cổ giới đồng thời xuất hiện một Huyết Hoàng vị thành niên và thi thể của một Phượng Hoàng trưởng thành.","nguonGoc":"Không rõ","tonChi":"Không rõ","quyMo":"Không rõ","tranPhai":["Phượng ngô Tiên cầm"],"thanhVien":[{"ten":"Vị thành niên đọa lạc Huyết Hoàng","chucVu":"Thành viên vị thành niên","tuChuong":"@c1339","trangThai":"còn sống"},{"ten":"Thi thể Phượng Hoàng trưởng thành","chucVu":"Thành viên trưởng thành","tuChuong":"@c1339","trangThai":"đã chết"}],"quanHe":"Không rõ","trangThai":"Không rõ","capNhatToi":"@c1339","tabs":{"tienTrinh":[{"chuong":"@c1339","loai":"nhắc tới","importance":"bridge","giaiDoan":"Dấu tích trong cổ giới","text":"Ngôn ngữ riêng, thần thụ tổ địa và hai Phượng Hoàng trong cổ giới hé lộ thêm dấu tích của bộ tộc.","anchor":"bởi vì không người hiểu bộ tộc Phượng Hoàng ngôn ngữ"}]},"nguon":["@c1339"]},{"id":"cuu-thien","name":"Cửu Thiên","cn":"","type":"the-luc","typeLabel":"Thế lực","diaBan":"Cửu Thiên","nhanVatChinh":["Mạnh Thiên Chính","Tào Vũ Sinh"],"blurb":"Thế lực của nhóm cường giả được Mạnh Thiên Chính bảo hộ khi tiến vào khu mộ tiên.","detail":"Nhóm Cửu Thiên bị Tiên thi và Bất Hủ thi hài vây giết, đồng thời không thể vượt hư không vì cổ trận. Họ công kích nữ tử xương trắng cùng lúc với phía Dị vực nhưng không hình thành liên minh chính thức, sau đó bị trường vực từ quan tài cản đường rời đi.","quanHe":"Đối địch với Dị vực nhưng cùng tìm cách thoát khỏi vòng vây tại mộ tiên.","trangThai":"Mắc kẹt tại mộ tiên","capNhatToi":"@c1340","tabs":{"tienTrinh":[{"chuong":"@c1340","loai":"khai chiến","importance":"normal","giaiDoan":"Vòng vây mộ tiên","text":"Đoàn Cửu Thiên chống lại Tiên thi và Bất Hủ thi hài, vượt qua tuyến của nữ tử xương trắng nhưng bị trường vực trong quan tài kéo lại.","anchor":"Lúc này, Cửu Thiên bên này người cũng vọt qua, vừa vặn nhìn thấy tình cảnh này"}]},"nguon":["@c1340"]},{"id":"de-toc-an-lan","name":"Đế tộc An Lan","cn":"","type":"gia-toc","typeLabel":"Đế tộc","diaBan":"Dị vực","nhanVatChinh":["An Lan"],"blurb":"Một Đế tộc cổ xưa của dị vực, được đặt trên các Vương tộc thông thường. Tuổi trẻ Đế Giả của tộc này vẫn chưa chính thức rời cổ địa.","detail":"Chư vương dị vực nhắc Đế tộc An Lan như một trong những gia tộc cổ xưa có tuổi trẻ Đế Giả thực sự. Những nhân vật trẻ tuổi này được xem là lực lượng mạnh hơn các vương giả đang xuất hiện.","quyMo":"Đế tộc cổ xưa của dị vực, đứng trên Vương tộc.","trangThai":"Tồn tại","capNhatToi":"@c1342","tabs":{"tienTrinh":[{"chuong":"@c1342","loai":"nhắc tới","importance":"bridge","giaiDoan":"Đế Giả trẻ tuổi chưa xuất thế","text":"Đế tộc An Lan được nhắc đến như một cổ xưa gia tộc có tuổi trẻ Đế Giả chưa chính thức rời cổ địa.","anchor":"còn có Đế tộc, An Lan, Du Đà các loại cổ xưa gia tộc tuổi trẻ Đế Giả chính thức đi ra"},{"chuong":"@c1354","loai":"nhắc tới","importance":"normal","giaiDoan":"Uy danh Tiên cổ","text":"Các lão giả giảng giải rằng tên An Lan là cấm kỵ và lực công kích của bộ tộc này từng chấn động thời Tiên cổ.","anchor":"An Lan hai chữ là cấm kỵ, lực công kích kinh Tiên cổ","trangThaiMoc":"Tồn tại tại dị vực"}]},"nguon":["@c1342","@c1354"]},{"id":"de-toc-du-da","name":"Đế tộc Du Đà","cn":"","type":"gia-toc","typeLabel":"Đế tộc","diaBan":"Dị vực","nhanVatChinh":["Du Đà"],"blurb":"Một Đế tộc cổ xưa của dị vực, được nhắc cùng Đế tộc An Lan. Tộc này có tuổi trẻ Đế Giả chưa chính thức bước ra khỏi cổ địa.","detail":"Đế tộc Du Đà được chư vương dị vực dùng làm minh chứng rằng lực lượng trẻ tuổi mạnh nhất của dị vực vẫn chưa xuất hiện. Địa vị của gia tộc này vượt trên các Vương tộc thông thường.","quyMo":"Đế tộc cổ xưa của dị vực.","trangThai":"hưng","capNhatToi":"@c1342","tabs":{"tienTrinh":[{"chuong":"@c1342","loai":"nhắc tới","importance":"bridge","giaiDoan":"Đế Giả trẻ tuổi chưa xuất thế","text":"Đế tộc Du Đà được nhắc đến như một cổ xưa gia tộc có tuổi trẻ Đế Giả chưa chính thức rời cổ địa.","anchor":"An Lan, Du Đà các loại cổ xưa gia tộc tuổi trẻ Đế Giả"}]},"nguon":["@c1342"]},{"id":"vuong-hi-gia-toc","name":"Vương Hi gia tộc","cn":"","type":"gia-toc","typeLabel":"Trường Sinh thế gia","diaBan":"Vô Lượng Thiên","nhanVatChinh":["Vương Hi","Vương Trường Sinh"],"blurb":"Gia tộc Trường Sinh của Vương Hi và Vương Trường Sinh. Người của gia tộc này xuất hiện tại Thiên Thần Thư Viện và gây áp lực lên những người vừa trở về từ tiền tuyến.","detail":"Ngay trước thời điểm đại chiến, người của Vương Hi gia tộc vào Thiên Thần Thư Viện, chất vấn Thạch Hạo và Tào Vũ Sinh rồi gọi họ là đào binh. Việc họ có thể xuất hiện và lên mặt tại đây khiến Thạch Hạo nhận thấy một tín hiệu nguy hiểm.","quanHe":"Có quan hệ đối địch và căng thẳng với Thạch Hạo cùng Mạnh Thiên Chính.","trangThai":"hoạt động","capNhatToi":"@c1342","tabs":{"tienTrinh":[{"chuong":"@c1342","loai":"mở rộng/mất địa bàn","importance":"normal","giaiDoan":"Xuất hiện trong thư viện","text":"Người của Vương Hi gia tộc tiến vào Thiên Thần Thư Viện, chất vấn những người trở về từ tiền tuyến và gây áp lực ngay trước đại chiến.","anchor":"người của Vương gia như thế nào đi vào Thiên Thần Thư Viện, lúc này khoa tay múa chân"}]},"nguon":["@c1342"]},{"id":"thien-giac-nghi-tien-phu","name":"Thiên Giác Nghĩ Tiên phủ","cn":"","aliases":[],"type":"the-luc","typeLabel":"Tiên phủ","diaBan":"Vô Lượng Thiên","nhanVatChinh":["Thiên Giác Nghĩ","Thủ lĩnh năm chiến binh khôi lỗi","Bốn chiến binh khôi lỗi còn lại"],"blurb":"Tiên phủ gắn với Thiên Giác Nghĩ và là nơi lưu giữ năm chiến binh khôi lỗi cổ xưa. Những khôi lỗi này từng chiến đấu chống dị vực và tuyệt đối phục tùng sự điều động của Thiên Giác Nghĩ.","detail":"Khi nhận ra nguy hiểm tại Thiên Thần Thư Viện, Thiên Giác Nghĩ bí mật đi dưới lòng đất tới Tiên phủ điều binh. Năm chiến binh mặc hắc giáp từ đây tới cứu viện; họ không còn là sinh linh chân chính nhưng thủ lĩnh vẫn có thể nói và nhớ về chiến trường xưa.","nguonGoc":"Tiên phủ gắn với Thiên Giác Nghĩ","tranPhai":"Năm chiến binh khôi lỗi cổ xưa","thanhVien":[{"ten":"Thủ lĩnh năm chiến binh khôi lỗi","chucVu":"Thủ lĩnh chiến binh khôi lỗi","tuChuong":"@c1344","trangThai":"đang hoạt động"},{"ten":"Bốn chiến binh khôi lỗi còn lại","chucVu":"Chiến binh khôi lỗi","tuChuong":"@c1344","trangThai":"đang hoạt động"}],"trangThai":"Đang hoạt động","capNhatToi":"@c1344","tabs":{"tienTrinh":[{"chuong":"@c1344","loai":"nhắc tới","importance":"normal","giaiDoan":"Điều viện binh","text":"Thiên Giác Nghĩ tới Tiên phủ điều năm chiến binh khôi lỗi làm viện quân cho Thiên Thần Thư Viện.","anchor":"đi ra mấy cái người mặc hắc giáp vàng trụ binh lính, không tính chân chính sinh động sinh vật, đã hóa thành con rối","trangThaiMoc":"Năm chiến binh khôi lỗi được điều động"}]},"nguon":["@c1344"]},{"id":"ha-vien-vuong-gia-gan-thien-than-thu-vien","name":"Hạ viện Vương gia gần Thiên Thần Thư Viện","cn":"","type":"hoc-vien","typeLabel":"Hạ viện kiêm cứ điểm","diaBan":"Vùng núi gần một tòa cự thành và Thiên Thần Thư Viện","nhanVatChinh":["Người trung niên cầm đầu hạ viện Vương gia","Hai người trẻ tuổi canh gác hạ viện Vương gia"],"blurb":"Hạ viện do Vương gia thiết lập gần Thiên Thần Thư Viện, vừa thu nhận đệ tử vừa giữ vai trò cứ điểm giám thị. Cứ điểm cuối cùng bị chiến thuyền của đoàn Thạch Hạo phá hủy, người cầm đầu bị bắt và xử tử.","detail":"Vương gia dựng hạ viện này gần Thiên Thần Thư Viện, thiết lập đạo trường, pháo đài và đại trận phòng hộ để làm cơ sở thu nhận đệ tử kiêm cứ điểm giám thị. Tại @c1345, chiến thuyền của đoàn Thạch Hạo phá xuyên đại trận và các kiến trúc trong hạ viện; người cầm đầu bị bắt rồi xử tử, khiến lực lượng tại đây tan rã.","nguonGoc":"Do Vương gia thiết lập làm hạ viện và cứ điểm gần Thiên Thần Thư Viện.","tonChi":"Thu nhận đệ tử, dựng đạo trường và giám thị khu vực lân cận Thiên Thần Thư Viện.","lanhDaoHienThoi":"Không còn người chỉ huy được xác nhận","quyMo":"Một pháo đài cổ có đại trận phòng hộ và nhiều kiến trúc","trangThai":"Bị phá hủy","thanhVien":[{"ten":"Người trung niên cầm đầu hạ viện Vương gia","chucVu":"Người cầm đầu","tuChuong":"@c1345","trangThai":"Đã chết"},{"ten":"Hai người trẻ tuổi canh gác hạ viện Vương gia","chucVu":"Canh gác","tuChuong":"@c1345","trangThai":"Còn sống"}],"capNhatToi":"@c1345","tabs":{"tienTrinh":[{"chuong":"@c1345","loai":"diệt/sáp nhập","importance":"major","giaiDoan":"Bị công phá","trangThaiMoc":"Bị phá hủy","text":"Chiến thuyền của đoàn Thạch Hạo phá xuyên đại trận và kiến trúc hạ viện; người cầm đầu bị bắt rồi xử tử.","anchor":"xem như là Vương gia một chỗ hạ viện, cũng thu đệ tử"}]},"nguon":["@c1345"],"dacDiem":"Là hạ viện của Vương gia đặt gần Thiên Thần Thư Viện, đồng thời đảm nhiệm vai trò đạo trường, nơi thu nhận đệ tử và cứ điểm giám thị có pháo đài cùng đại trận phòng hộ.","congNang":["Dùng đại trận để phòng hộ hạ viện và cứ điểm, nhưng đã bị chiến thuyền của đoàn Thạch Hạo phá xuyên @c1345."]},{"id":"doi-quan-lao-binh-cua-thien-giac-nghi","name":"Đội quân lão binh của Thiên Giác Nghĩ","cn":"","type":"quan-doi","typeLabel":"Đội quân Tiên Cổ","diaBan":"Thiên Thần Thư Viện","nhanVatChinh":["Thủ lĩnh năm binh sĩ con rối","Năm binh sĩ con rối của Thiên Giác Nghĩ"],"blurb":"Đội quân cũ của Thiên Giác Nghĩ nay chỉ còn năm lão binh khôi lỗi cùng một tàn kỳ.","detail":"Năm lão binh từng tham chiến với dị vực và được Thiên Giác Nghĩ ban phù văn chúc phúc. Tại Thiên Thần Thư Viện, họ phá chiến trận Vương gia, giết Vương Cát cùng Vương Chân.","nguonGoc":"Đội quân dưới quyền Thiên Giác Nghĩ từ thời Tiên Cổ","lanhDaoHienThoi":"Thủ lĩnh năm binh sĩ con rối","quyMo":"Chỉ còn năm lão binh","tranPhai":["Tiên gia chiến kỳ"],"trangThai":"tàn quân","thanhVien":[{"ten":"Thủ lĩnh năm binh sĩ con rối","chucVu":"Thủ lĩnh","tuChuong":"@c1347","trangThai":"đang hoạt động"},{"ten":"Bốn chiến binh khôi lỗi còn lại","chucVu":"Lão binh","tuChuong":"@c1347","trangThai":"đang hoạt động"}],"lanhDaoMoc":[{"ten":"Thủ lĩnh năm binh sĩ con rối","tuChuong":"@c1347","denChuong":""}],"tabs":{"tienTrinh":[{"chuong":"@c1347","loai":"khai chiến","importance":"normal","giaiDoan":"Phá chiến trận Vương gia","text":"Năm lão binh phá tan chiến trận Vương gia và giết hai nhân vật trọng yếu của đối phương.","anchor":"thuộc về chúng ta này một đội nhân mã, cứ việc chỉ còn lại có năm người","trangThaiMoc":"tàn quân"}]},"capNhatToi":"@c1347","nguon":["@c1347"]},{"id":"kim-gia","name":"Kim gia","cn":"","type":"gia-toc","typeLabel":"Trường Sinh thế gia","diaBan":"Thanh Vi Thiên","nhanVatChinh":["Kim thái quân","Kim Triển"],"blurb":"Trường Sinh thế gia ở Thanh Vi Thiên, do Kim thái quân đại diện trong cuộc đối chất tại Thiên Thần Thư Viện.","detail":"Kim gia có quan hệ thông gia với Vương gia qua hôn ước giữa Kim Triển và Vương Hi. Kim thái quân đích thân vượt giới để cứu năm con rồng Vương gia nhưng không thể lay chuyển quyết định đưa họ ra Biên Hoang.","lanhDaoHienThoi":"Kim thái quân","caoThuManhNhat":"Kim thái quân","quanHe":"Thông gia với Vương gia qua hôn ước giữa Kim Triển và Vương Hi.","trangThai":"Đang hoạt động","thanhVien":[{"ten":"Kim thái quân","chucVu":"Cổ tổ, cao thủ số một","tuChuong":"@c1352","trangThai":"đang hoạt động"},{"ten":"Kim Triển","chucVu":"Thiên kiêu","tuChuong":"@c1352","trangThai":"tu hành tại Thánh Viện"}],"lanhDaoMoc":[{"ten":"Kim thái quân","tuChuong":"@c1352","denChuong":""}],"capNhatToi":"@c1352","tabs":{"tienTrinh":[{"chuong":"@c1352","loai":"liên minh","importance":"normal","giaiDoan":"Can thiệp cho Vương gia","text":"Kim thái quân đại diện Kim gia vượt giới cầu tình cho năm con rồng, thể hiện quan hệ thông gia chặt chẽ với Vương gia, nhưng sự can thiệp không thành.","anchor":"Vương gia cùng Kim gia thông gia, quả nhiên là như thể chân tay","trangThaiMoc":"Liên minh thông gia với Vương gia"}]},"nguon":["@c1352"]},{"id":"cac-truong-sinh-the-gia","name":"Các Trường Sinh thế gia","cn":"","aliases":[],"type":"gia-toc","typeLabel":"Nhóm Trường Sinh thế gia","diaBan":"Cửu Thiên","nhanVatChinh":["Các chúa tể Trường Sinh thế gia"],"blurb":"Nhóm các Trường Sinh thế gia có những người quyết định tối cao tham gia xử lý đại cục trước cuộc chiến biên hoang.","detail":"Sau khi Vương gia điều mười vạn tinh binh, một cự đầu Trường Sinh thế gia cùng Mạnh Thiên Chính dẫn quân tới biên hoang, trong khi các cự đầu khác rời đi hoặc tiếp tục lưu thủ Cửu Thiên.","quyMo":"Có nhiều người quyết định tối cao và tuyệt thế cao thủ.","caoThuManhNhat":"Các cự đầu Trường Sinh thế gia","quanHe":"Phối hợp với Mạnh Thiên Chính đưa quân tới biên hoang.","trangThai":"Phân công người tham chiến và lưu thủ","capNhatToi":"@c1353","thanhVien":[{"ten":"Các chúa tể Trường Sinh thế gia","chucVu":"Người quyết định tối cao","tuChuong":"@c1353","trangThai":"Một người tham chiến, những người khác rời đi hoặc lưu thủ"}],"tabs":{"tienTrinh":[{"chuong":"@c1353","loai":"khai chiến","importance":"normal","giaiDoan":"Phân công lực lượng","text":"Một cự đầu Trường Sinh thế gia cùng Mạnh Thiên Chính dẫn quân tới biên hoang, trong khi Cửu Thiên vẫn giữ lại cự đầu phòng thủ.","anchor":"tại Đại trưởng lão còn có Trường Sinh thế gia một vị cự đầu dưới sự hướng dẫn","trangThaiMoc":"Phân người tham chiến và lưu thủ"}]},"nguon":["@c1353"]},{"id":"de-toc-co-lao-nhat-di-vuc","name":"Đế Tộc cổ lão nhất dị vực","cn":"","type":"de-toc","typeLabel":"Đế Tộc","diaBan":"Dị vực","nhanVatChinh":[],"blurb":"Một Đế Tộc dị vực cực kỳ cổ xưa, tồn tại trước cả hai tộc An Lan và Du Đà.","detail":"Bộ tộc có thiên phú miễn dịch thần thông và pháp lực, từ đó phát triển thành tổ thuật khiến vạn pháp đều diệt. Thạch Hạo xem tộc này là đối thủ có thể giúp hắn hoàn thiện năng lực miễn dịch pháp lực của bản thân.","nguonGoc":"Dị vực","dacDiem":"Cổ xưa hơn hai Đế Tộc An Lan và Du Đà, sở hữu thiên phú miễn dịch vạn pháp.","caoThuManhNhat":"Không rõ","trangThai":"Tồn tại","capNhatToi":"@c1354","tabs":{"tienTrinh":[{"chuong":"@c1354","loai":"nhắc tới","importance":"normal","giaiDoan":"Thân phận được hé lộ","text":"Các lão giả tiết lộ một Đế Tộc cổ xưa hơn An Lan và Du Đà, có thực lực đáng sợ cùng thiên phú miễn dịch vạn pháp.","anchor":"thậm chí An Lan, Du Đà hai tộc còn phải xa xưa hơn, thực lực đáng sợ","trangThaiMoc":"Tồn tại tại dị vực"}]},"nguon":["@c1354"]},{"id":"than-co-toc","name":"Thần Cô tộc","cn":"","type":"chung-toc","typeLabel":"Chủng tộc dị vực","diaBan":"Dị vực","nhanVatChinh":[],"blurb":"Một chủng tộc dị vực có số lượng cực ít nhưng sức mạnh đáng sợ, bắt nguồn từ nhánh Cô tộc phản bội thuộc Thập Hung.","detail":"Sau khi phản bội và tiến vào dị vực, nhánh này phát sinh dị biến rồi trở nên mạnh hơn. Tộc nhân được mô tả có tay trái đoạn không gian và tay phải đoạn thời gian; một cao thủ tuyệt thế của tộc từng tung đòn cuối nhằm vào Lục Đạo Luân Hồi Tiên Vương.","nguonGoc":"Một nhánh Cô tộc thuộc Thập Hung phản bội sang dị vực","quyMo":"Số lượng cực ít","caoThuManhNhat":"Cao thủ tuyệt thế từng tham chiến cuối thời Tiên cổ","soCaoThu":"Không rõ","quanHe":"Đối địch Cửu Thiên; có nguồn gốc từ Cô tộc thuộc Thập Hung","trangThai":"Tồn tại tại dị vực","capNhatToi":"@c1358","tabs":{"tienTrinh":[{"chuong":"@c1358","loai":"nhắc tới","importance":"normal","giaiDoan":"Hé lộ nguồn gốc","text":"Các tiền bối công bố Thần Cô tộc vốn là một nhánh Cô tộc thuộc Thập Hung phản bội sang dị vực, sau đó dị biến và trở nên mạnh hơn.","anchor":"chúng nó mạch này chính là sinh ra với Thập Hung bên trong cô tộc phản lại đi"}]},"nguon":["@c1358"]},{"id":"quan-thu-thanh-de-quan","name":"Quân thủ thành Đế quan","cn":"","aliases":[],"type":"quan-doi","typeLabel":"Quân đội trấn thủ","diaBan":"Đế Thành tại Biên Hoang","nhanVatChinh":[],"blurb":"Lực lượng thường trực bảo vệ Đế quan, gồm tu sĩ trấn thủ tường thành, đại kỵ sĩ, thần tiễn thủ và viện quân từ Cửu Thiên Thập Địa.","detail":"Quân thủ thành giao chiến thường xuyên với dị vực, có thể tiêu diệt địch và bắt tù binh trở về. Dù nhiều đợt viện quân đã khiến binh lực tăng mạnh, số người tử trận mỗi ngày vẫn rất lớn.","tonChi":"Trấn thủ Đế quan và ngăn dị vực tiến vào Cửu Thiên Thập Địa","quyMo":"Được viện quân Cửu Thiên Thập Địa bổ sung nhiều lần, có những đội quân lên tới hàng chục nghìn người.","quanHe":"Đối địch với quân dị vực","trangThai":"Đang trấn thủ và giao chiến","capNhatToi":"@c1360","tabs":{"tienTrinh":[{"chuong":"@c1360","loai":"khai chiến","importance":"normal","giaiDoan":"Chiến sự Biên Hoang","text":"Quân thủ thành giành được chiến quả và bắt tù binh dị vực, nhưng đồng thời phải chịu thương vong lớn dù viện quân đã bổ sung binh lực nhiều lần.","anchor":"Lần trước, Cửu Thiên Thập Địa viện quân tới rồi, để trong thành chiến sĩ gia tăng rồi rất nhiều lần"}]},"nguon":["@c1360"]},{"id":"bien-hoang-bay-vuong","name":"Biên Hoang bảy Vương","cn":"","aliases":["Thất Vương"],"type":"nhom-cuong-gia","typeLabel":"Nhóm cường giả","diaBan":"Biên Hoang","nhanVatChinh":["Tổ tiên Thạch Tộc","Tổ tiên Hỏa tộc","Chiến hữu của tổ tiên Thạch Tộc và Hỏa tộc"],"blurb":"Nhóm bảy cường giả gắn với Biên Hoang. Ba người trong số họ được lưu hình và chấp niệm trên khắc đá tại tổ đàn.","detail":"Chương này xác nhận tổ tiên Thạch Tộc, tổ tiên Hỏa tộc và chiến hữu của họ đều thuộc Biên Hoang bảy Vương. Sinh tử hiện thời của ba người vẫn chưa rõ.","nguonGoc":"Gắn với việc trấn thủ Biên Hoang","caoThuManhNhat":"Không rõ","soCaoThu":"Bảy Vương","trangThai":"Sinh tử của ba thành viên được nhắc vẫn chưa rõ","capNhatToi":"@c1363","thanhVien":[{"ten":"Tổ tiên Thạch Tộc","chucVu":"Một trong bảy Vương","tuChuong":"@c1363","trangThai":"Không rõ sinh tử"},{"ten":"Tổ tiên Hỏa tộc","chucVu":"Một trong bảy Vương","tuChuong":"@c1363","trangThai":"Không rõ sinh tử"},{"ten":"Chiến hữu của tổ tiên Thạch Tộc và Hỏa tộc","chucVu":"Một trong bảy Vương","tuChuong":"@c1363","trangThai":"Không rõ sinh tử"}],"tabs":{"tienTrinh":[{"chuong":"@c1363","loai":"nhắc tới","importance":"normal","giaiDoan":"Xác nhận ba thành viên","text":"Ba người trên khắc đá được xác nhận là ba thành viên trong Biên Hoang bảy Vương.","anchor":"Bọn họ là bảy Vương bên trong là ba người?","trangThaiMoc":"Sinh tử chưa rõ"},{"chuong":"@c1365","loai":"nhắc tới","importance":"bridge","giaiDoan":"Ký ức huyết chiến","text":"Thạch Hạo nhớ lại cảnh Biên Hoang bảy Vương trấn thủ Biên Hoang và huyết chiến đến cùng.","anchor":"chính mắt thấy Thất Vương nuôi thủ Biên Hoang, huyết chiến đến cùng cảnh tượng"}]},"nguon":["@c1363","@c1365"]},{"id":"thach-toc-tai-de-quan","name":"Thạch Tộc tại Đế quan","cn":"","aliases":[],"type":"gia-toc","typeLabel":"Gia tộc","diaBan":"Bộ lạc Thạch Tộc trong Đế Thành","nhanVatChinh":["Lão già bộ lạc Thạch Tộc","Tráng niên bộ lạc Thạch Tộc","A Thú","Cha của A Thú","Thạch Hạo"],"blurb":"Một nhánh Thạch Tộc từng là đại tộc hùng mạnh tại Đế quan nhưng suy tàn sau khi bị quy thành hậu duệ Tội Huyết.","detail":"Thạch Tộc từng đông người, cao thủ như mây và có quyền lên tiếng lớn tại Đế quan. Sau khi vụ án cũ bị khơi lại, tộc nhân bị buộc đứng ở tuyến đầu mỗi lần xuất chinh; thiên tài cùng cao thủ chết dần qua nhiều thế hệ, khiến bộ lạc hiện chỉ còn hơn một nghìn người.","quyMo":"Hơn một nghìn người","trangThai":"Suy","quanHe":"Bị nhiều thế lực tại Đế quan chèn ép vì thân phận hậu duệ Tội Huyết.","thanhVien":[{"ten":"Lão già bộ lạc Thạch Tộc","chucVu":"Trưởng bối","tuChuong":"@c1364","trangThai":"Đang sống"},{"ten":"Tráng niên bộ lạc Thạch Tộc","chucVu":"Tộc nhân","tuChuong":"@c1364","trangThai":"Đang sống"},{"ten":"A Thú","chucVu":"Thiếu niên trong tộc","tuChuong":"@c1364","trangThai":"Đang sống"},{"ten":"Cha của A Thú","chucVu":"Chiến sĩ","tuChuong":"@c1364","trangThai":"Đã tử trận"}],"tabs":{"tienTrinh":[{"chuong":"@c1364","loai":"suy","importance":"normal","giaiDoan":"Đại tộc suy tàn","text":"Việc liên tục bị buộc chiến đấu ở tuyến đầu khiến cao thủ và thiên tài Thạch Tộc chết dần, toàn tộc chỉ còn hơn một nghìn người.","anchor":"một cái đại tộc suy thoái, máu và xương còn có lệ","trangThaiMoc":"Suy"}]},"capNhatToi":"@c1364","nguon":["@c1364"]},{"id":"dai-quan-de-quan","name":"Đại quân Đế quan","cn":"","type":"quan-doi","typeLabel":"Thế lực quân sự","diaBan":"Đế quan và chiến trường quan ngoại","nhanVatChinh":["Đại kỵ sĩ cưỡi Thôn Thiên thú","Các lão giả trên tế đàn","Đại kỵ sĩ Độn Nhất cảnh","Lão kỵ sĩ cưỡi Tỳ Hưu"],"blurb":"Lực lượng quân sự gồm nhiều nhánh quân đội và chủng tộc đóng tại Đế quan. Các đội ngũ hội quân trên tế đàn rồi đồng loạt vượt giới môn tiến ra chiến trường quan ngoại.","detail":"Đại quân được điều động từ khu vực tập kết, nhận lời cổ vũ chiến đấu bảo vệ người thân và sử dụng tế đàn giới môn để xuất quan. Lực lượng bao gồm nhiều đội ngũ, các chủng tộc và những sinh linh có hình thể khổng lồ.","quyMo":"Nhiều nhánh quân đội và chủng tộc","trangThai":"Đã xuất quan tiến vào chiến trường","thanhVien":[{"ten":"Đại kỵ sĩ cưỡi Thôn Thiên thú","chucVu":"Đại kỵ sĩ chỉ huy một nhánh quân","tuChuong":"@c1369","trangThai":"Đang phục vụ"},{"ten":"Các lão giả trên tế đàn","chucVu":"Người vận hành tế đàn","tuChuong":"@c1369","trangThai":"Đang phục vụ"},{"ten":"Đại kỵ sĩ Độn Nhất cảnh","chucVu":"Đại kỵ sĩ","tuChuong":"@c1369","trangThai":"Đang phục vụ"},{"ten":"Lão kỵ sĩ cưỡi Tỳ Hưu","chucVu":"Kỵ sĩ","tuChuong":"@c1369","trangThai":"Đang phục vụ"}],"capNhatToi":"@c1369","tabs":{"tienTrinh":[{"chuong":"@c1369","loai":"khai chiến","importance":"normal","giaiDoan":"Đại quân xuất quan","text":"Các nhánh quân đội và chủng tộc hội quân tại tế đàn rồi vượt giới môn tiến ra chiến trường quan ngoại.","anchor":"các tộc quân đội toàn bộ điều động, bắt đầu xuất phát","trangThaiMoc":"Đã xuất quan"}]},"nguon":["@c1369"]},{"id":"hoang-kim-da-xoa-toc","name":"Hoàng kim Dạ Xoa tộc","cn":"","type":"vuong-toc","typeLabel":"Đại Vương tộc","diaBan":"Dị vực","nhanVatChinh":["Hoàng kim Dạ Xoa trẻ tuổi"],"blurb":"Một Đại Vương tộc nổi danh của dị vực, thường nằm trong nhóm mười lăm Vương tộc hàng đầu. Một vương giả trẻ tuổi của tộc bị Thạch Hạo đánh chết trên chiến trường hai giới.","detail":"Hoàng kim Dạ Xoa tộc nổi tiếng về sức mạnh thân thể. Trong cuộc đối quyết cùng cấp, thành viên trẻ tuổi của tộc vẫn bị Thạch Hạo áp đảo và đánh nổ toàn thân.","quyMo":"Thường nằm trong mười lăm Đại Vương tộc hàng đầu của dị vực.","thanhVien":[{"ten":"Hoàng kim Dạ Xoa trẻ tuổi","chucVu":"Vương giả trẻ tuổi","tuChuong":"@c1372","trangThai":"Đã chết"}],"capNhatToi":"@c1372","tabs":{"tienTrinh":[{"chuong":"@c1372","loai":"nhắc tới","importance":"normal","giaiDoan":"Vương giả tử trận","text":"Một vương giả trẻ tuổi của Hoàng kim Dạ Xoa tộc được phái giao chiến cùng cấp và bị Thạch Hạo đánh chết.","anchor":"tộc này trường kỳ có thể đứng vào mười vị trí đầu năm Đại Vương tộc bên trong","trangThaiMoc":"Một thành viên trẻ tuổi tử trận"}]},"nguon":["@c1372"]},{"id":"de-quan-the-luc","name":"Đế quan","cn":"","type":"quan-su","typeLabel":"Thế lực quân sự","diaBan":"Đệ nhất hùng quan tại Biên Hoang","nhanVatChinh":["Đại kỵ sĩ cưỡi kim Tỳ Hưu","Thạch Hậu Đức"],"blurb":"Lực lượng trấn thủ hùng quan và chống lại đại quân dị vực.","detail":"Đế quan tổ chức kiểm tra nghiêm ngặt đoàn quân trở về và luân phiên đưa chiến sĩ các tộc ra ngoài quan luyện binh, chuẩn bị cho ngày Thiên Uyên không còn che chở.","tonChi":"Trấn thủ Biên Hoang và chuẩn bị lực lượng đối đầu dị vực.","quyMo":"Tập hợp chiến sĩ của nhiều tộc trong hùng quan.","quanHe":"Đối địch với Dị vực.","trangThai":"Tiếp tục luân phiên luyện binh","thanhVien":[{"ten":"Đại kỵ sĩ cưỡi kim Tỳ Hưu","chucVu":"Đại kỵ sĩ","tuChuong":"@c1377","trangThai":"Đang phục vụ"},{"ten":"Thạch Hậu Đức","chucVu":"Tộc trưởng một bộ lạc trong Đế quan","tuChuong":"@c1377","trangThai":"Đang sinh sống"}],"capNhatToi":"@c1377","tabs":{"tienTrinh":[{"chuong":"@c1377","loai":"nhắc tới","importance":"normal","giaiDoan":"Luân phiên luyện binh","text":"Đế quan tiếp tục đưa các tộc ra quan ngoại chiến đấu để mài giũa quân sĩ cho trận quyết chiến tương lai.","anchor":"Đây là đang luyện binh, mà không nghi ngờ chút nào, tình huống này sẽ kéo dài","trangThaiMoc":"Tiếp tục luyện binh"}]},"dinhDanh":"goc","nguon":["@c1377"]},{"id":"ba-truong-sinh-the-gia-trong-de-quan","name":"Ba Trường Sinh thế gia trong Đế quan","cn":"","type":"gia-toc","typeLabel":"Nhóm thế gia","diaBan":"Đế quan","nhanVatChinh":[],"blurb":"Ba Trường Sinh thế gia có hậu duệ được mời tới thiên tài thịnh hội tại Bích Lạc hồ.","detail":"Người truyền tin giới thiệu hậu duệ của ba gia tộc này như một nhóm khách dự hội đáng chú ý.","capNhatToi":"@c1378","nguon":["@c1378"]},{"id":"ve-gia","name":"Vệ gia","cn":"","type":"truong-sinh-the-gia","typeLabel":"Trường sinh thế gia","diaBan":"Đế Quan","nhanVatChinh":["Vệ gia Tứ Hoàng"],"blurb":"Một trong ba Trường sinh thế gia tại Đế Quan, không thuộc Nhân tộc. Gia tộc có truyền thừa thần bí, cổ xưa và sở hữu bốn nữ thiên tài được gọi là Tứ Hoàng.","detail":"Vệ gia sống cách biệt với ngoại giới nên sinh linh Cửu Thiên ít biết về họ. Trong thế hệ hiện tại, bốn nữ tử kinh diễm của gia tộc có thể liên thủ quét ngang những người cùng tuổi.","nguonGoc":"Thế lực cổ xưa không thuộc Nhân tộc","quyMo":"Một trong ba Trường sinh thế gia tại Đế Quan","trangThai":"Đang tồn tại","capNhatToi":"@c1379","thanhVien":[{"ten":"Vệ gia Tứ Hoàng","chucVu":"Bốn thiên tài trẻ","tuChuong":"@c1379","trangThai":"Đang thuộc gia tộc"}],"tabs":{"tienTrinh":[{"chuong":"@c1379","loai":"nhắc tới","importance":"normal","giaiDoan":"Lộ diện tại thịnh hội","text":"Vệ gia được giới thiệu là một trong ba Trường sinh thế gia của Đế Quan khi bốn nữ thiên tài trong tộc tiến vào Bích Lạc hồ.","anchor":"Vệ gia, cũng không phải là Nhân tộc, thế nhưng Đế Quan bên trong tam đại Trường sinh thế gia một trong, cùng ngoại giới ngăn cách, Cửu Thiên sinh linh căn bản không biết, truyền thừa thập phần thần bí cùng cổ xưa.","trangThaiMoc":"Đang tồn tại"}]},"nguon":["@c1379"]},{"id":"thac-co-gia-toc","name":"Thác Cổ gia tộc","cn":"","type":"truong-sinh-the-gia","typeLabel":"Trường sinh thế gia","diaBan":"Đế Quan","nhanVatChinh":["Thác Cổ Ngự Long","Thác Cổ Lạc Nhạn"],"blurb":"Một trong ba Trường sinh thế gia tại Đế Quan và là hậu duệ Chân Tiên. Gia tộc có ít thành viên nhưng thực lực mạnh, trong cơ thể tộc nhân còn chảy một phần Tiên huyết.","detail":"Thế hệ trẻ của Thác Cổ gia tộc có Thác Cổ Ngự Long, người được xem là Chân Long trong tộc, cùng em gái Thác Cổ Lạc Nhạn. Đoàn của họ tới Bích Lạc hồ bằng hai Thiểm điện chiến xa.","nguonGoc":"Hậu duệ Chân Tiên mang một phần Tiên huyết","quyMo":"Một trong ba Trường sinh thế gia tại Đế Quan, nhân khẩu không nhiều","caoThuManhNhat":"Thác Cổ Ngự Long trong thế hệ trẻ","trangThai":"Đang tồn tại","capNhatToi":"@c1379","thanhVien":[{"ten":"Thác Cổ Ngự Long","chucVu":"Thiên kiêu trẻ","tuChuong":"@c1379","trangThai":"Đang thuộc gia tộc"},{"ten":"Thác Cổ Lạc Nhạn","chucVu":"Tộc nhân trẻ","tuChuong":"@c1379","trangThai":"Đang thuộc gia tộc"}],"tabs":{"tienTrinh":[{"chuong":"@c1379","loai":"nhắc tới","importance":"normal","giaiDoan":"Truyền nhân tới Bích Lạc hồ","text":"Thác Cổ gia tộc được giới thiệu là hậu duệ Chân Tiên khi đoàn của Thác Cổ Ngự Long và Thác Cổ Lạc Nhạn tới dự thịnh hội.","anchor":"Thác Cổ gia tộc, là Đế Quan tam đại Trường sinh thế gia một trong, là Chân Tiên hậu duệ, trong cơ thể chảy xuôi bộ phận Tiên huyết, nhân khẩu cũng không nhiều, thế nhưng tộc này vô cùng mạnh mẽ.","trangThaiMoc":"Đang tồn tại"}]},"nguon":["@c1379"]},{"id":"vung-cam-tren-chin-tang-troi","name":"Vùng cấm trên chín tầng trời","cn":"","type":"khu-vuc-cam","typeLabel":"Thế lực vùng cấm","diaBan":"Vùng cấm trên chín tầng trời","nhanVatChinh":[],"blurb":"Các vùng cấm bí ẩn trên chín tầng trời, nơi sinh linh bên ngoài hiếm khi được nhìn thấy. Tin có sinh linh vùng cấm nhận thiệp mời vào Đế quan khiến đại hội Bích Lạc hồ chấn động.","detail":"Sự điều động của sinh linh vùng cấm được coi là tin tức lớn vì họ vốn ít xuất hiện trước ngoại giới và có thể tham dự thịnh hội tại Đế quan.","trangThai":"Có tin sinh linh được điều động tới Đế quan","capNhatToi":"@c1380","tabs":{"tienTrinh":[{"chuong":"@c1380","loai":"nhắc tới","importance":"normal","giaiDoan":"Có thể tham dự thịnh hội","text":"Tin sinh linh vùng cấm được điều động tới Đế quan trở thành tiêu điểm nghị luận tại Bích Lạc hồ.","anchor":"Vùng cấm thật sự có sinh linh điều động, đến Đế quan?"}]},"nguon":["@c1380"]},{"id":"lien-minh-kim-gia-va-vuong-gia","name":"Hai tộc Kim gia và Vương gia","cn":"","type":"lien-minh","typeLabel":"Liên minh gia tộc","diaBan":"Cửu Thiên","nhanVatChinh":["Kim Triển","Vương Hi","Mười hai thúc tổ của Vương Hi","Ngũ thúc tổ của Kim Triển"],"blurb":"Sự phối hợp lợi ích giữa Kim gia và Vương gia nhằm vun đắp Kim Triển thành người đứng đầu thế hệ trẻ.","detail":"Hai tộc ngăn Kim Triển mạo hiểm quyết chiến với Thạch Hạo vì muốn duy trì danh thế bất bại, qua đó để hắn lĩnh quân thế hệ trẻ và tạo ảnh hưởng tại Cửu Thiên.","tonChi":"Vun đắp Kim Triển thành đệ nhất nhân thế hệ trẻ.","quanHe":"Kim gia và Vương gia cùng phối hợp bảo toàn danh thế của Kim Triển.","trangThai":"Đang hợp tác","capNhatToi":"@c1384","thanhVien":[{"ten":"Kim Triển","chucVu":"Nhân vật được hai tộc vun đắp","tuChuong":"@c1384","trangThai":"đang được bảo vệ"},{"ten":"Mười hai thúc tổ của Vương Hi","chucVu":"Trưởng bối Vương gia","tuChuong":"@c1384","trangThai":"đang tham gia"},{"ten":"Ngũ thúc tổ của Kim Triển","chucVu":"Trưởng bối Kim gia","tuChuong":"@c1384","trangThai":"đang tham gia"}],"tabs":{"tienTrinh":[{"chuong":"@c1384","loai":"liên minh","importance":"normal","giaiDoan":"Bảo toàn danh thế Kim Triển","text":"Hai tộc phối hợp ngăn Kim Triển quyết chiến với Thạch Hạo để duy trì kế hoạch đưa hắn lên vị trí đứng đầu thế hệ trẻ.","anchor":"Hai tộc phải đem Kim Triển đắp nặn vì là thế hệ tuổi trẻ đệ nhất nhân"}]},"nguon":["@c1384"]},{"id":"dai-quan-di-vuc","name":"Đại quân dị vực","cn":"","aliases":[],"type":"quân đội","typeLabel":"Quân đội","diaBan":"Dị vực","nhanVatChinh":[],"blurb":"Lực lượng đối địch với tiên dân Cửu Thiên trong chiến trường Tiên cổ được thiên kiếp tái hiện.","detail":"Trong dị tượng thiên kiếp, đại quân dị vực giao chiến với tiên dân trên Cửu Thiên. Tại Thập Địa, vô số thi thể thuộc phía dị vực sống dậy và mang binh khí vây công Thạch Hạo.","trangThai":"Được thiên kiếp tái hiện","capNhatToi":"@c1386","nguon":["@c1386"]},{"id":"tien-dan-cuu-thien-thap-dia","name":"Tiên dân Cửu Thiên Thập Địa","cn":"","type":"lien-minh","typeLabel":"Lực lượng bản địa","diaBan":"Cửu Thiên Thập Địa","nhanVatChinh":[],"blurb":"Lực lượng tiên dân bảo vệ gia đình và sơn hà trước cuộc xâm lược của dị vực. Dù ở thế yếu, họ vẫn liều chết xung phong.","detail":"Trong kiếp cảnh của Thạch Hạo, tiên dân Cửu Thiên Thập Địa bị đại quân dị vực áp đảo nhưng vẫn kiên quyết tử chiến. Tinh thần không sợ chết của họ khiến Thạch Hạo cảm hóa và tiếp tục tham gia cuộc huyết sát.","tonChi":"Bảo vệ thân quyến và sơn hà trước quân xâm lược.","quyMo":"Hiện diện trên các chiến trường và khu dân cư của Cửu Thiên Thập Địa.","quanHe":"Đối địch với Đại quân dị vực.","trangThai":"Suy yếu nhưng vẫn kháng cự","capNhatToi":"@c1388","tabs":{"tienTrinh":[{"chuong":"@c1388","loai":"khai chiến","importance":"normal","giaiDoan":"Kháng cự dị vực","text":"Tiên dân ở thế yếu vẫn liều chết xung phong bảo vệ thân quyến và sơn hà trước cuộc xâm lược của dị vực.","anchor":"Tiên dân ở rống to, ở xung phong, hãn không sợ chết","trangThaiMoc":"Suy yếu nhưng tiếp tục tử chiến"}]},"nguon":["@c1388"]}]};
